'use server'

import { getLiabilityAccounts, getLiabilityReport } from './services/liabilityServices';
import { createSuccessResponse, createErrorResponse } from '@/types/response.type';

export async function getLiabilityAccountsAction() {
  try {
    const data = await getLiabilityAccounts();
    return createSuccessResponse(data);
  } catch (error) {
    console.error('getLiabilityAccountsAction error:', error);
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch liability accounts',
      'LIABILITY_ACCOUNTS_ERROR'
    );
  }
}

export async function getLiabilityReportAction() {
  try {
    const data = await getLiabilityReport();
    return createSuccessResponse(data);
  } catch (error) {
    console.error('getLiabilityReportAction error:', error);
    return createErrorResponse(
      error instanceof Error ? error.message : 'Failed to fetch liability report',
      'LIABILITY_REPORT_ERROR'
    );
  }
}
