import { prisma } from '@/lib/prisma';
import type { LiabilityAccount, MutasiEntry } from '../types/liability.type';
import type { LiabilityRow } from '@/types/report.type';

export async function getLiabilityAccounts() {
  const accounts = await prisma.account.findMany({
    where: {
      bucket: 'LIABILITY',
      isActive: true,
    },
    include: {
      ledgerEntries: {
        orderBy: { date: 'desc' }
      }
    },
    orderBy: { name: 'asc' },
  });

  const mappedAccounts: LiabilityAccount[] = accounts.map((acc) => ({
    id: String(acc.id),
    nama: acc.name,
    tipe: acc.type,
    currency: acc.currency,
    saldo: Number(acc.balance),
    updatedAt: acc.updatedAt.toISOString(),
    aktif: acc.isActive,
  }));

  const mappedMutasi: Record<string, MutasiEntry[]> = {};
  accounts.forEach((acc) => {
    mappedMutasi[String(acc.id)] = (acc.ledgerEntries || []).map((entry) => ({
      tanggal: entry.date.toISOString(),
      arah: entry.direction,
      nominal: Number(entry.amount),
      kategori: entry.refType || "Lainnya",
      catatan: entry.note || "",
    }));
  });

  return { accounts: mappedAccounts, mutasi: mappedMutasi };
}

export async function getLiabilityReport() {
  const accounts = await prisma.account.findMany({
    where: {
      bucket: 'LIABILITY',
      isActive: true,
    },
    include: {
      ledgerEntries: true
    }
  });

  const allEntries: any[] = [];
  accounts.forEach((acc) => {
    if (acc.ledgerEntries) {
      acc.ledgerEntries.forEach((entry) => {
        allEntries.push({
          ...entry,
          accountName: acc.name,
        });
      });
    }
  });

  // Sort entries by date ascending
  allEntries.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  let runningOutstandingDebt = 0;
  const mappedRows: LiabilityRow[] = allEntries.map((entry) => {
    const isRepayment = entry.direction === "CREDIT";
    const nominal = Number(entry.amount);

    if (isRepayment) {
      runningOutstandingDebt = runningOutstandingDebt - nominal;
    } else {
      runningOutstandingDebt = runningOutstandingDebt + nominal;
    }

    return {
      tanggal: entry.date.toISOString(),
      keterangan: entry.note || (isRepayment ? "Pembayaran Hutang" : "Bunga"),
      tipe: (isRepayment ? "Pembayaran" : "Bunga") as "Pembayaran" | "Bunga",
      kategori: entry.refType || "Lainnya",
      metode: entry.accountName,
      nominal: nominal,
      saldoOutstanding: Math.abs(runningOutstandingDebt),
    };
  });

  // Sort back to descending for display (newest first)
  mappedRows.sort((a, b) => new Date(b.tanggal).getTime() - new Date(a.tanggal).getTime());

  return mappedRows;
}
